mapper.update:
UPDATE appt_slot_capacity
SET booked_count = booked_count + 1
WHERE lane_id = #{laneId}
  AND appt_date = #{apptDate}
  AND time_slot = #{timeSlot}
  AND booked_count < capacity

UPDATE appt_slot_capacity
SET booked_count = GREATEST(booked_count - 1, 0)
WHERE lane_id = #{laneId}
  AND appt_date = #{apptDate}
  AND time_slot = #{timeSlot}

mapper.select:
SELECT booked_count FROM appt_slot_capacity
WHERE lane_id = #{laneId} AND appt_date = #{apptDate} AND time_slot = #{timeSlot}
LIMIT 1

SELECT t.time_slot AS timeSlot, GREATEST(IFNULL(s.capacity, #{defaultCapacity}) - IFNULL(s.booked_count, 0), 0) AS remain FROM (
SELECT #{slot} AS time_slot
) t LEFT JOIN appt_slot_capacity s ON s.lane_id = #{laneId} AND s.appt_date = #{date} AND s.time_slot = t.time_slot ORDER BY t.time_slot
